INSERT INTO `chat_messages` (`id`, `conversation_id`, `role`, `content`, `tokens_used`, `created_at`) VALUES
(1, 1, 'user', 'What packages do you offer?', NULL, '2026-09-26 19:47:43'),
(2, 1, 'assistant', 'Hello! 👋 Thanks for reaching out to WooBD.Com.\n\nWe offer a variety of packages tailored for online stores, custom websites, and digital storefronts. To see the latest details and specific pricing in BDT, please check our **Services page** here: [http://localhost:3000/services](http://localhost:3000/services)\n\nI can’t quote exact prices directly, but if you have questions about features or delivery times after reviewing the page, I’m happy to help! You can also connect with our team via WhatsApp at **+8801789668276** or email us at **hello@woobd.com**.\n\nHow else can I assist you today? 😊', NULL, '2026-09-26 19:47:49'),
(3, 2, 'user', 'What packages do you offer?', NULL, '2026-09-26 19:48:03'),
(4, 2, 'assistant', 'Hello! 👋 Thanks for reaching out to WooBD.Com.\n\nWe offer a variety of packages tailored for online stores, custom websites, and digital storefronts. To see the latest details and specific pricing in BDT, please check our **Services page** here: [http://localhost:3000/services](http://localhost:3000/services)\n\nI can’t quote exact prices directly, but if you have questions about features or delivery times after reviewing the page, I’m happy to help! You can also connect with our team via WhatsApp at **+8801789668276** or email us at **hello@woobd.com**.\n\nHow else can I assist you today? 😊', NULL, '2026-09-26 19:48:04'),
(5, 3, 'user', 'What packages do you offer?', NULL, '2026-09-26 19:48:40'),
(6, 3, 'assistant', 'Hello! 👋 Thanks for reaching out to WooBD.Com.\n\nWe offer a variety of packages tailored for online stores, custom websites, and digital storefronts. To see the latest details and specific pricing in BDT, please check our **Services page** here: [http://localhost:3000/services](http://localhost:3000/services)\n\nI can’t quote exact prices directly, but if you have questions about features or delivery times after reviewing the page, I’m happy to help! You can also connect with our team via WhatsApp at **+8801789668276** or email us at **hello@woobd.com**.\n\nHow else can I assist you today? 😊', NULL, '2026-09-26 19:48:40'),
(7, 4, 'user', 'What packages do you offer?', NULL, '2026-09-26 19:49:50'),
(8, 4, 'assistant', 'Hello! 👋 Thanks for reaching out to WooBD.Com.\n\nWe offer a variety of packages tailored to your needs, including **Online Stores**, **Custom Websites**, and **Digital Storefronts**.\n\nTo see the specific features and current pricing (in BDT) for each package, please visit our services page here: [http://localhost:3000/services](http://localhost:3000/services)\n\nIf you have any questions after checking the list, feel free to ask! We’re happy to help you find the right fit. 😊', NULL, '2026-09-26 19:49:56');
