INSERT INTO `pages` (`id`, `title`, `slug`, `content`, `featured_image`, `meta_title`, `meta_description`, `meta_keywords`, `canonical_url`, `robots`, `og_title`, `og_description`, `og_image`, `show_in_footer`, `status`, `created_at`, `updated_at`) VALUES
(1, 'Privacy Policy', 'privacy-policy', '\n<p><strong>Last updated:</strong> 27 September 2026</p>\n\n<h3>1. Who we are</h3>\n<p>WooBD.Com is a website design and development agency located at Dhaka, Bangladesh. You can reach us at\n<a href="mailto:hello@woobd.com">hello@woobd.com</a> or +880 1700 000000.</p>\n\n<h3>2. Information we collect</h3>\n<p>We collect information you give us directly, including your name, email address, phone number, company name\nand the contents of any message or support ticket you send us. When you place an order we also collect the\nproject details you provide.</p>\n\n<h3>3. Payment information</h3>\n<p>When you pay by bKash, Nagad or Rocket, you submit a transaction ID and the mobile number used to send the\npayment. We use this only to verify that payment was received. We do not collect or store your PIN, OTP, card\nnumber or any other payment credential.</p>\n\n<h3>4. How we use your information</h3>\n<p>We use your information to respond to enquiries, deliver the services you order, issue invoices, provide\nsupport, and send you transactional messages about your account. With your consent we may also send occasional\nservice updates.</p>\n\n<h3>5. Sharing</h3>\n<p>We do not sell your personal information. We share it only with service providers who help us operate —\nfor example our hosting provider and email delivery service — and only to the extent necessary.</p>\n\n<h3>6. Cookies and sessions</h3>\n<p>We use a session cookie to keep you signed in and a local storage entry to remember your colour theme\npreference. We use Google reCAPTCHA on our sign-in, sign-up and contact forms to prevent automated abuse.</p>\n\n<h3>7. Data retention</h3>\n<p>We retain account and order records for as long as your account is active and for a reasonable period\nafterwards to meet accounting and legal obligations.</p>\n\n<h3>8. Your rights</h3>\n<p>You may request a copy of the information we hold about you, ask us to correct it, or ask us to delete\nyour account. Email <a href="mailto:hello@woobd.com">hello@woobd.com</a> and we will respond within 30 days.</p>\n\n<h3>9. Security</h3>\n<p>We protect your information with encrypted connections (HTTPS), hashed passwords, restricted admin access\nand regular software updates. No system is perfectly secure, but we take these obligations seriously.</p>\n\n<h3>10. Changes</h3>\n<p>We may update this policy from time to time. Material changes will be announced on this page with a new\n"last updated" date.</p>\n', NULL, NULL, 'How WooBD.Com collects, uses and protects your information.', NULL, NULL, 'index,follow', NULL, NULL, NULL, 1, 'published', '2026-09-26 13:59:40', '2026-09-27 10:13:25'),
(2, 'Terms & Conditions', 'terms-conditions', '', '/uploads/pages/upload-test-0e479b91.png', 'Terms &amp;amp;amp;amp; Conditions - WooBD.Com', '', '', '', 'index,follow', '', '', '', 1, 'published', '2026-09-26 13:59:40', '2026-09-28 10:22:05'),
(3, 'Refund Policy', 'refund-policy', '<h2>Refund Policy</h2>\n<p><strong>Last updated:</strong> 1 January 2025</p>\n<p>We want you to be confident ordering from us. This policy explains exactly when a refund is available, so there are no surprises.</p>\n\n<h3>1. Before work begins</h3>\n<p>If you cancel before we have started any work on your order, you receive a full refund of the amount paid, less any payment processing fee charged to us by the gateway. Notify us by email or through your dashboard ticket system.</p>\n\n<h3>2. After work has started</h3>\n<p>If we have begun design or development, we retain payment for the work completed and refund the remainder. We will tell you the exact percentage retained and show you the work delivered to date. As a guide: design phase carries 40% of the project value, build phase 80%, and delivery 100%.</p>\n\n<h3>3. After delivery</h3>\n<p>Once your website has been delivered and your credentials published in your dashboard, the project is complete and the fee is non-refundable. If something is genuinely broken or differs from the agreed scope, we will fix it at no cost - that is a support matter, not a refund matter.</p>\n\n<h3>4. Recurring plans</h3>\n<p>Care Plans, SEO packages and marketing retainers renew monthly. You may cancel at any time from your dashboard, and the cancellation takes effect at the end of the current billing period. We do not refund partial months already in progress, but we will not charge you again after cancellation.</p>\n\n<h3>5. Hosting and domain fees</h3>\n<p>Hosting and domain registration are paid to third-party providers and are not refundable by us once registered. Domain registrations cannot be reversed after purchase under registrar policy.</p>\n\n<h3>6. Non-refundable situations</h3>\n<ul>\n<li>A completed project where you have received and used the website</li>\n<li>Delays caused by you not supplying content, product data or hosting access</li>\n<li>Dissatisfaction with a design after you have approved it in the revision stage</li>\n<li>Third-party service failures, such as a payment gateway suspending your merchant account</li>\n<li>Subscription periods already billed and partially elapsed</li>\n</ul>\n\n<h3>7. How to request a refund</h3>\n<p>Open a support ticket from your dashboard under the Billing department, or email hello@woobd.com with your order number. Include what went wrong so we can assess it properly. We acknowledge every request within one business day and issue a decision within five business days.</p>\n\n<h3>8. How refunds are paid</h3>\n<p>Approved refunds are returned by the same method you paid with, within seven business days of approval. If you paid by card, allow additional time for your bank to post the credit.</p>\n\n<h3>9. Contact</h3>\n<p>Questions about a refund: <a href="mailto:hello@woobd.com">hello@woobd.com</a> or WhatsApp +8801789668276.</p>', NULL, 'Refund Policy - WooBD.Com', 'When WooBD.Com issues refunds on website design and development orders, and how to request one.', NULL, NULL, 'index,follow', NULL, NULL, NULL, 0, 'published', '2026-09-26 13:59:40', '2026-09-26 13:59:40'),
(4, 'About WooBD.Com', 'about-us', '<h2>About WooBD.Com</h2>\n<p>We build e-commerce websites for Bangladeshi businesses - the kind that take real orders, accept bKash, and survive a Friday-night traffic spike.</p>\n<p>WooBD.Com started in Rangpur in 2019 after watching too many good local businesses lose sales to a website that never worked properly. A store owner would pay for a site, wait three months, receive something slow and broken, and go back to selling through Facebook Messenger. We thought that was a fixable problem.</p>\n<p>Our approach is different in one specific way: we hand over everything. When your website goes live, your cPanel URL, admin credentials and database details appear in your own dashboard. You are never locked in, never dependent on us to make a text change, and never held hostage over a domain. If you leave, you leave with everything.</p>\n<p>Since 2019 we have delivered over 200 websites across Dhaka, Chittagong, Sylhet, Khulna, Rajshahi, Bogra and Rangpur - fashion stores, electronics retailers, agricultural suppliers, restaurants and cooperatives. Most of our work now comes from referrals.</p>', NULL, 'About Us - WooBD.Com', 'WooBD.Com is a Rangpur-based web design agency building e-commerce websites for Bangladeshi businesses since 2019.', NULL, NULL, 'index,follow', NULL, NULL, NULL, 0, 'published', '2026-09-26 13:59:40', '2026-09-26 13:59:40');
