INSERT INTO `portfolio` (`id`, `title`, `slug`, `client_name`, `category`, `short_description`, `description`, `thumbnail`, `gallery`, `project_url`, `completed_at`, `technologies`, `is_featured`, `status`, `sort_order`, `seo_title`, `seo_description`, `created_at`, `updated_at`) VALUES
(1, 'Rangpur Fashion House', 'rangpur-fashion-house', 'Rangpur Fashion House', 'Fashion &amp; Apparel', '', '', '/uploads/portfolio/upload-test-5e3e9f21.png', '[]', '', '2026-01-15 00:00:00', '[]', 1, 'active', 0, 'Rangpur Fashion House - Case Study - WooBD.Com', '', '2026-09-26 13:59:40', '2026-09-27 11:07:47'),
(2, 'Dhaka Electronics Mart', 'dhaka-electronics-mart', 'Dhaka Electronics Mart', 'Electronics', 'Multi-brand electronics store with warranty tracking and EMI checkout.', '<p>A high-ticket electronics retailer needed customers to trust a BDT 80,000 purchase to a website. We added serial-number warranty registration, an EMI calculator on every product page, and a comparison tool for competing models.</p>', '/assets/img/portfolio-default.svg', '[]', NULL, '2024-05-02 00:00:00', '["WordPress","WooCommerce","Custom plugin","SSLCommerz"]', 1, 'active', 1, 'Dhaka Electronics Mart - Case Study - WooBD.Com', 'Multi-brand electronics store with warranty tracking and EMI checkout.', '2026-09-26 13:59:40', '2026-09-26 13:59:40'),
(3, 'Chittagong Agro Supplies', 'chittagong-agro-supplies', 'Chittagong Agro Supplies', 'Agriculture', 'B2B ordering portal for agricultural inputs, with dealer pricing tiers.', '<p>Dealers needed to see their own negotiated prices, not retail ones. We built role-based pricing tiers, bulk order upload via CSV, and a credit-terms checkout that issues an invoice instead of taking payment online.</p>', '/assets/img/portfolio-default.svg', '[]', NULL, '2024-11-20 00:00:00', '["WordPress","WooCommerce B2B","Custom roles"]', 0, 'active', 2, 'Chittagong Agro Supplies - Case Study - WooBD.Com', 'B2B ordering portal for agricultural inputs, with dealer pricing tiers.', '2026-09-26 13:59:40', '2026-09-26 13:59:40'),
(4, 'Sylhet Tea Collective', 'sylhet-tea-collective', 'Sylhet Tea Collective', 'Food & Beverage', 'Subscription tea delivery for a cooperative of twelve growers.', '<p>A recurring-revenue build: customers subscribe to a monthly box, choose their blend profile, and can pause from their own dashboard. The twelve member growers each get a sales report for their own lots.</p>', '/assets/img/portfolio-default.svg', '[]', NULL, '2025-01-10 00:00:00', '["WordPress","WooCommerce Subscriptions","bKash"]', 1, 'active', 3, 'Sylhet Tea Collective - Case Study - WooBD.Com', 'Subscription tea delivery for a cooperative of twelve growers.', '2026-09-26 13:59:40', '2026-09-26 13:59:40'),
(5, 'Khulna Home Decor', 'khulna-home-decor', 'Khulna Home Decor', 'Home & Living', 'Visual-first furniture store with room-view browsing and delivery scheduling.', '<p>Furniture is bought with the eye. We built a lookbook-driven catalogue where shoppers browse by room, plus a delivery slot picker that respects the store\'s two-truck routing constraint.</p>', '/assets/img/portfolio-default.svg', '[]', NULL, '2024-09-28 00:00:00', '["WordPress","WooCommerce","Custom lookbook"]', 0, 'active', 4, 'Khulna Home Decor - Case Study - WooBD.Com', 'Visual-first furniture store with room-view browsing and delivery scheduling.', '2026-09-26 13:59:40', '2026-09-26 13:59:40'),
(6, 'Bogra Sports Gear', 'bogra-sports-gear', 'Bogra Sports Gear', 'Sports', 'Performance-optimised store that cut load time from 6.1s to 1.4s.', '<p>The client came to us with a slow store and a high bounce rate, not a redesign request. We rebuilt the hosting stack, converted images to WebP, removed four abandoned plugins, and added object caching. Load time dropped from 6.1s to 1.4s and mobile conversion nearly doubled.</p>', '/assets/img/portfolio-default.svg', '[]', NULL, '2025-02-18 00:00:00', '["WordPress","Redis","WebP","LiteSpeed"]', 0, 'active', 5, 'Bogra Sports Gear - Case Study - WooBD.Com', 'Performance-optimised store that cut load time from 6.1s to 1.4s.', '2026-09-26 13:59:40', '2026-09-26 13:59:40');
INSERT INTO `posts` (`id`, `title`, `slug`, `category`, `excerpt`, `content`, `reading_minutes`, `view_count`, `is_featured`, `featured_image`, `author_id`, `status`, `published_at`, `seo_title`, `seo_description`, `meta_keywords`, `canonical_url`, `robots`, `og_title`, `og_description`, `og_image`, `created_at`, `updated_at`) VALUES
(1, 'How to choose a payment gateway for a Bangladeshi online store', 'choose-payment-gateway-bangladesh', 'Guides', 'bKash, Nagad, Rocket or card — what each one costs you, which your customers actually use, and how to set them up without losing a sale at checkout.', '<p>Choosing how to take money is the single decision that most affects whether a Bangladeshi store converts. Get it wrong and customers fill a basket, reach the payment step and leave.</p>\n\n<h2>What your customers actually use</h2>\n<p>Mobile wallets dominate. bKash is the default for most buyers, Nagad is close behind, and Rocket has a smaller but loyal base. Card payments matter for corporate buyers and for anyone spending above roughly 10,000 taka.</p>\n\n<h2>The real cost of each option</h2>\n<p>Every wallet charges a settlement fee, and it is rarely the number people quote you. Ask for the all-in figure: the gateway fee, the settlement fee, and how long the money takes to reach your bank.</p>\n\n<h3>Cash on delivery is not free either</h3>\n<p>Roughly a third of cash-on-delivery parcels come back. Budget for the return trip, the repackaging and the courier\'s time — it is usually more than the wallet fee you were trying to avoid.</p>\n\n<h2>How to set them up</h2>\n<p>Start with one wallet and cash on delivery. Add the second wallet once you have a month of data showing customers abandoning at checkout. Adding every option on day one gives you four reconciliation spreadsheets and no extra sales.</p>\n\n<h2>What to check before you go live</h2>\n<p>Place a real order for the smallest amount you sell. Refund it. Watch how long the money takes to come back. That single test tells you more than any comparison table.</p>', 1, 463, 1, NULL, 1, 'published', '2026-09-27 09:57:33', 'How to choose a payment gateway for a Bangladeshi online store', 'bKash, Nagad, Rocket or card — what each one costs you, which your customers actually use, and how to set them up without losing a sale at checkout.', NULL, NULL, 'index,follow', NULL, NULL, NULL, '2026-09-27 15:57:33', '2026-09-28 11:07:13'),
(2, 'Why your product photos are costing you sales', 'product-photos-costing-sales', 'Design', 'Most stores do not have a traffic problem, they have a photograph problem. Here is what to fix first, and what you can safely ignore.', '<p>A customer cannot touch your product. The photograph is the product. Everything else — the description, the reviews, the price — is read after the decision has already started forming.</p>\n\n<h2>The three things that matter</h2>\n<p>Sharpness, a consistent background, and enough angles that the buyer stops wondering. Nothing else on this list has the same effect.</p>\n\n<h3>Consistency beats quality</h3>\n<p>Twelve photos shot on a phone against the same white wall look more professional than twelve studio shots with different lighting. Buyers read inconsistency as carelessness.</p>\n\n<h2>What you can ignore</h2>\n<p>Fancy lifestyle photography, video, and 360-degree spins. All of them help at the margin. None of them fix a blurry hero image.</p>\n\n<h2>A one-hour fix</h2>\n<p>Pick your ten best-selling products. Reshoot them against one background in one session. Replace the current images. Measure conversion over the next fortnight.</p>', 1, 268, 1, NULL, 1, 'published', '2026-09-24 09:57:33', 'Why your product photos are costing you sales', 'Most stores do not have a traffic problem, they have a photograph problem. Here is what to fix first, and what you can safely ignore.', NULL, NULL, 'index,follow', NULL, NULL, NULL, '2026-09-27 15:57:33', '2026-09-27 15:57:33'),
(3, 'The hidden cost of a slow website', 'hidden-cost-of-a-slow-website', 'Performance', 'Every extra second of load time costs you roughly a tenth of your mobile visitors. Here is where that time actually goes.', '<p>Speed is not a technical metric. It is the number of people who leave before they see anything.</p>\n\n<h2>Where the time goes</h2>\n<p>Almost always the same three places: an unoptimised hero image, a font loaded from a third party, and a plugin that runs before the page can paint.</p>\n\n<h2>What to measure</h2>\n<p>Not your desktop score. Open the site on a mid-range Android phone on a mobile connection — that is your customer, and that is the number that matters.</p>\n\n<h2>What to fix first</h2>\n<p>Compress the hero image. It is usually worth more than every other optimisation combined, and it takes ten minutes.</p>', 1, 195, 0, NULL, 1, 'published', '2026-09-21 09:57:33', 'The hidden cost of a slow website', 'Every extra second of load time costs you roughly a tenth of your mobile visitors. Here is where that time actually goes.', NULL, NULL, 'index,follow', NULL, NULL, NULL, '2026-09-27 15:57:33', '2026-09-27 15:57:33'),
(4, 'Writing product descriptions that sell in Bangladesh', 'product-descriptions-that-sell', 'Copywriting', 'The same product, described two ways, converts at wildly different rates. The difference is almost never the adjectives.', '<p>Most product descriptions describe the product. The ones that sell describe the customer\'s day after buying it.</p>\n\n<h2>Lead with the outcome</h2>\n<p>Not "100% cotton" but "survives a Dhaka summer without fading". The specification is evidence; the outcome is the reason.</p>\n\n<h2>Answer the question they are about to ask</h2>\n<p>Every category has one. Clothing: will it fit? Electronics: is it genuine? Furniture: will it survive the delivery?</p>\n\n<h2>Keep it short</h2>\n<p>Three short paragraphs beat one long one. Mobile buyers scan; nobody reads a wall of text before deciding.</p>', 1, 154, 0, NULL, 1, 'published', '2026-09-18 09:57:33', 'Writing product descriptions that sell in Bangladesh', 'The same product, described two ways, converts at wildly different rates. The difference is almost never the adjectives.', NULL, NULL, 'index,follow', NULL, NULL, NULL, '2026-09-27 15:57:33', '2026-09-27 15:57:33'),
(5, 'Setting up your first online store: a checklist', 'first-online-store-checklist', 'Guides', 'Everything that has to be true before you take your first order, in the order it needs to happen.', '<p>Most first stores fail on the boring items — a missing returns policy, a phone number nobody answers, a payment method that only works on weekdays.</p>\n\n<h2>Before you build</h2>\n<p>Decide what you sell, who buys it, and how it reaches them. The website is the last step, not the first.</p>\n\n<h2>Before you launch</h2>\n<p>Delivery times you can actually meet, a returns policy you can afford, and someone answering messages within a working day.</p>\n\n<h2>Before your first ad</h2>\n<p>Place an order yourself. Refund it. Ask a friend to place one. Fix whatever confused them.</p>', 1, 121, 0, NULL, 1, 'published', '2026-09-15 09:57:33', 'Setting up your first online store: a checklist', 'Everything that has to be true before you take your first order, in the order it needs to happen.', NULL, NULL, 'index,follow', NULL, NULL, NULL, '2026-09-27 15:57:33', '2026-09-27 15:57:33'),
(6, 'What we learned rebuilding a store for mobile', 'rebuilding-for-mobile', 'Case study', 'Nine in ten visitors were on a phone and the site had been designed on a laptop. Here is what changed and what it moved.', '<p>The brief was simple: mobile conversion was a third of desktop. The cause was not simple, but it was findable.</p>\n\n<h2>What we found</h2>\n<p>The checkout button fell below the fold on a 360px screen. Everything else was a rounding error.</p>\n\n<h2>What we changed</h2>\n<p>Rebuilt the product page mobile-first, moved the add-to-cart button into a sticky bar, and cut the hero image to a quarter of its size.</p>\n\n<h2>What it moved</h2>\n<p>Mobile conversion roughly doubled over the following month. Desktop barely moved, which is what you would expect — it was never the problem.</p>', 1, 98, 0, NULL, 1, 'published', '2026-09-12 09:57:33', 'What we learned rebuilding a store for mobile', 'Nine in ten visitors were on a phone and the site had been designed on a laptop. Here is what changed and what it moved.', NULL, NULL, 'index,follow', NULL, NULL, NULL, '2026-09-27 15:57:33', '2026-09-27 15:57:33');
