(7, NULL, 'Website Care Plan - Basic', 'website-care-plan-basic', '', '', '/uploads/packages/upload-test-45e6c256.png', 2500, NULL, 'monthly', 1, 1, 0, '[]', 1, 'active', 6, 'Website Care Plan - Basic - WooBD.Com', '', 4, '2026-09-26 13:59:40', '2026-09-27 14:32:14'),
(8, 3, 'Website Care Plan - Business', 'website-care-plan-business', 'Everything in Basic plus performance work, priority support and monthly content updates.', '<p>For stores where downtime directly costs sales. Includes a monthly performance and conversion review, not just maintenance.</p>', '/assets/img/service-default.svg', 5500, NULL, 'monthly', 1, 1, 0, '["Everything in Basic plan","Daily backups (90-day retention)","Speed optimisation each month","Image and database cleanup","Up to 5 hours content edits per month","Product uploads (up to 50 per month)","Priority email and WhatsApp support","Same-day emergency response","Monthly analytics report","Quarterly strategy call"]', 1, 'active', 7, 'Website Care Plan - Business - WooBD.Com', 'Everything in Basic plus performance work, priority support and monthly content updates.', 0, '2026-09-26 13:59:40', '2026-09-26 13:59:40'),
(9, 4, 'SEO Growth Package', 'seo-growth-package', 'Technical SEO, keyword targeting and content built to rank for buying-intent searches.', '<p>We start with a technical audit and a keyword map, then work outward: fix what blocks indexing, target the terms your buyers actually type, and build the authority to hold those positions.</p><p>Reporting is monthly and shows ranking movement per keyword, not vanity traffic numbers.</p>', '/assets/img/service-default.svg', 12000, NULL, 'monthly', 30, 1, 0, '["Full technical SEO audit","Keyword research and mapping","On-page optimisation (10 pages/month)","Meta title and description rewrite","Schema markup implementation","Google Search Console management","Broken link and redirect fixes","Blog content (2 articles/month)","Backlink outreach (5 links/month)","Competitor gap analysis","Monthly ranking report","Google My Business optimisation"]', 1, 'active', 8, 'SEO Growth Package - WooBD.Com', 'Technical SEO, keyword targeting and content built to rank for buying-intent searches.', 0, '2026-09-26 13:59:40', '2026-09-26 13:59:40'),
(10, 4, 'Google Ads Management', 'google-ads-management', 'Search and Shopping campaigns managed for return on ad spend, not clicks.', '<p>Campaign structure, negative keyword discipline and conversion tracking that actually attributes sales. We report on cost per acquisition, and we will tell you when a channel is not worth the budget.</p>', '/assets/img/service-default.svg', 15000, NULL, 'monthly', 7, 1, 0, '["Account audit and restructuring","Search campaign build","Shopping campaign setup","Keyword and negative keyword research","Ad copy writing and A/B testing","Conversion tracking implementation","Landing page recommendations","Bid strategy optimisation","Weekly optimisation pass","Monthly performance report"]', 0, 'active', 9, 'Google Ads Management - WooBD.Com', 'Search and Shopping campaigns managed for return on ad spend, not clicks.', 0, '2026-09-26 13:59:40', '2026-09-26 13:59:40'),
(11, 4, 'Social Media Marketing', 'social-media-marketing', 'Content, scheduling and community management for Facebook, Instagram and TikTok.', '<p>A consistent posting rhythm with creative built for the platform, plus reply management so no customer message sits unanswered over a weekend.</p>', '/assets/img/service-default.svg', 9000, NULL, 'monthly', 5, 1, 0, '["Content calendar (20 posts/month)","Graphic design for each post","Short-form video editing (4 reels)","Caption and hashtag research","Scheduling and publishing","Comment and DM management","Facebook Shop product tagging","Paid boost campaign setup","Monthly engagement report"]', 0, 'active', 10, 'Social Media Marketing - WooBD.Com', 'Content, scheduling and community management for Facebook, Instagram and TikTok.', 0, '2026-09-26 13:59:40', '2026-09-26 13:59:40'),
(12, 4, 'Conversion Rate Optimisation', 'conversion-rate-optimisation', 'Turn the traffic you already have into more orders - through testing, not guessing.', '<p>We instrument the funnel, find where people drop, and test fixes one variable at a time. Every change ships with a hypothesis and a measured result.</p>', '/assets/img/service-default.svg', 18000, NULL, 'monthly', 14, 1, 0, '["Funnel and heatmap analysis","Session recording review","Checkout flow audit","Hypothesis backlog creation","A/B test implementation","Product page optimisation","Cart abandonment analysis","Trust signal placement review","Mobile experience fixes","Bi-weekly test result report"]', 0, 'active', 11, 'Conversion Rate Optimisation - WooBD.Com', 'Turn the traffic you already have into more orders - through testing, not guessing.', 0, '2026-09-26 13:59:40', '2026-09-26 13:59:40'),
(22, 1, 'WooCommerce Web Design — Starter', 'woocommerce-web-design-starter', 'A complete WooCommerce store for a new seller — live in a week, from ৳999 a month.', '<p>Our entry WooCommerce package gets a real, working storefront online in about a week. We install WordPress and WooCommerce, configure a responsive theme, and set up the Bangladeshi payment methods your customers actually use.</p><p>Billed monthly with a three-month minimum, so you are not locked into a year before you know it works. Pay for twelve months up front and you save 10%.</p>', '/assets/img/service-default.svg', 999, NULL, 'monthly', 7, 3, 10, '["WordPress + WooCommerce installation","Responsive store theme configured","Up to 50 products uploaded","bKash / Nagad / Rocket payment setup","Cash on delivery configuration","SSL certificate installation","Contact form with email delivery","Basic on-page SEO","WhatsApp order button","Email support within 24 hours","Minimum 3-month plan"]', 1, 'active', 0, 'WooCommerce Web Design — Starter - WooBD.Com', 'A complete WooCommerce store for a new seller — live in a week, from ৳999 a month.', 250, '2026-09-26 17:36:50', '2026-09-28 11:07:25'),
(23, 1, 'WooCommerce Web Design — Business', 'woocommerce-web-design-business', 'A custom-designed WooCommerce store for a growing brand — up to 300 products, courier integration and marketing automation.', '<p>Our most popular build. A storefront designed around your brand rather than a stock theme, with the payment, delivery and marketing plumbing that turns visitors into repeat buyers.</p><p>Delivery is phased: design sign-off in week one, store build in week two, then training and handover. Billed monthly with a three-month minimum; pay for a year and save 10%.</p>', '/assets/img/service-default.svg', 2499, NULL, 'monthly', 14, 3, 10, '["Everything in the Starter package","Custom UI design (not a stock theme)","Up to 300 products uploaded","Full payment gateway integration","Courier / delivery API integration","Customer accounts and order tracking","Coupon, offer and discount engine","Meta Pixel + Google Analytics setup","Facebook Shop catalogue sync","Abandoned cart recovery","Invoice and packing slip templates","Priority support within 12 hours","Minimum 3-month plan"]', 1, 'active', 1, 'WooCommerce Web Design — Business - WooBD.Com', 'A custom-designed WooCommerce store for a growing brand — up to 300 products, courier integration and marketing automation.', 0, '2026-09-26 17:36:50', '2026-09-26 17:36:50'),
(24, 1, 'WooCommerce Web Design — Premium', 'woocommerce-web-design-premium', 'A high-volume WooCommerce store with custom development, integrations and dedicated infrastructure.', '<p>For catalogues past a thousand SKUs, multi-vendor marketplaces, or stores where a custom integration is unavoidable. Scoped individually — the list below is the typical shape, not a fixed promise.</p><p>Includes a dedicated staging environment so your live store is never touched during development, and a monthly strategy call. Billed monthly with a three-month minimum; pay for a year and save 10%.</p>', '/assets/img/service-default.svg', 4999, NULL, 'monthly', 21, 3, 10, '["Everything in the Business package","Up to 1,000 products uploaded","Multi-vendor marketplace support","Custom plugin / feature development","ERP or inventory system integration","Multi-currency and multi-language","Advanced analytics dashboard","Dedicated staging environment","Speed and load optimisation","Automated daily backups","Staff training session","Monthly strategy call","Priority support within 4 hours","Minimum 3-month plan"]', 1, 'active', 2, 'WooCommerce Web Design — Premium - WooBD.Com', 'A high-volume WooCommerce store with custom development, integrations and dedicated infrastructure.', 0, '2026-09-26 17:36:50', '2026-09-26 17:36:50');
